create table public.teachers (id uuid primary key default gen_random_uuid(), name text not null, phone text not null default '', subjects text[] not null default '{}', max_weekly_hours int not null default 0, working_days text[] not null default '{}', created_at timestamptz not null default now());
create table public.schedule_slots (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.teachers(id) on delete cascade, day_of_week text not null, period int not null, activity_type text not null, subject text, class_room text, unique(teacher_id,day_of_week,period));
create table public.substitutions (id uuid primary key default gen_random_uuid(), date date not null, day_of_week text not null, period int not null, original_teacher_id uuid not null references public.teachers(id) on delete cascade, substitute_teacher_id uuid not null references public.teachers(id) on delete cascade, reason text not null default '', status text not null default 'ממתין לאישור', subject text, class_room text, created_at timestamptz not null default now());
grant select on public.teachers, public.schedule_slots to anon, authenticated;
grant select, insert, update on public.substitutions to anon, authenticated;
grant all on public.teachers, public.schedule_slots, public.substitutions to service_role;
alter table public.teachers enable row level security;
alter table public.schedule_slots enable row level security;
alter table public.substitutions enable row level security;
create policy "read teachers" on public.teachers for select to anon, authenticated using (true);
create policy "read slots" on public.schedule_slots for select to anon, authenticated using (true);
create policy "read subs" on public.substitutions for select to anon, authenticated using (true);
create policy "add subs" on public.substitutions for insert to anon, authenticated with check (true);
create policy "update subs" on public.substitutions for update to anon, authenticated using (true) with check (true);
