ins as (insert into public.teachers(name) select name from raw returning id, name),
cells as (select i.id, regexp_match(c,'^(\d)(\d+)([hsp])([gkamyl]?)([א-ת]*)(\d?)$') m from ins i join raw r on r.name=i.name, unnest(string_to_array(r.body,',')) c where c<>'')
insert into public.schedule_slots(teacher_id,day_of_week,period,activity_type,subject,class_room)
select id, (array['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday'])[m[1]::int+1], m[2]::int,
 case m[3] when 'h' then 'הוראה' when 's' then 'שהייה' else 'פרטני' end,
 case m[4] when 'g' then 'חינוך גופני' when 'k' then 'הוראה כוללת' when 'a' then 'אמנות' when 'm' then 'מוסיקה' when 'y' then 'ישיבת צוות' when 'l' then 'מילוי מקום' else null end,
 case when m[5]<>'' then m[5]||''''||m[6] else null end
from cells where m is not null on conflict do nothing;
update public.teachers t set max_weekly_hours=(select count(*) from public.schedule_slots s where s.teacher_id=t.id),
 subjects=coalesce((select array_agg(distinct subject) from public.schedule_slots s where s.teacher_id=t.id and activity_type='הוראה' and subject is not null),'{}'),
 working_days=coalesce((select array_agg(d order by o) from unnest(array['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday']) with ordinality x(d,o) where exists(select 1 from public.schedule_slots s where s.teacher_id=t.id and s.day_of_week=x.d)),'{}');